//! The UI3 kit's cursors (private use only), generated from the kit's vectors: each a stack of
//! filled shapes (flattened and triangulated) on the kit's 32-unit box, the hot spot where the
//! pointer is. Shapes marked `shadow` cast the kit's drop shadow (down 1, blurred, 35% black).
#![allow(dead_code)]

/// One filled shape.
pub struct Layer {
    pub rgb: [u8; 3],
    pub shadow: bool,
    /// x, y pairs; the rings' points in order, one ring after another.
    pub verts: &'static [f32],
    /// Triangle indices into `verts` (pairs).
    pub tris: &'static [u16],
    /// Point counts of the rings, to outline them.
    pub rings: &'static [u16],
}

/// A cursor: its shapes, back to front, and its hot spot.
pub struct FigCursor {
    pub hot: [f32; 2],
    pub layers: &'static [Layer],
}

